class Turn(Enum):
    START = 1
    MIDDLE = 2
    END = 3

class User(BaseModel):
    name: str
    relation: str

class Message(BaseModel):
    user: User
    text: str

class Game(BaseModel):
    context: str
    turns: List[Message]

class Dialogue(BaseModel):
    context: str
    turns: List[Turn]

