        ```python
class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None
        self.parent = None

def create_tree(data):
    if not data:
        return None

    root = TreeNode(data[0])
    for i in range(1, len(data), 2):
        parent_value = data[i]
        child_value = data[i + 1]

        parent_node = find_node(root, parent_value)
        if parent_node:
            child_node = TreeNode(child_value)
            child_node.parent = parent_node
            parent_node.left = child_node
        else:
            root = TreeNode(child_value)

    return root

def find_node(root, value):
    if root is None:
        return None
    if root.value == value:
        return root
    node = find_node(root.left, value)
    if node:
        return node
    return find_node(root.right, value)

