import json

def generate_preceding_dialogue(context, reply):
    # Define Steve's messages
    steve_messages = [
        "You're being really unfair now.",
        "Come on, it's only happened once!",
        "come on, it happened like one time!",
    ]

    # Define u2's messages
    u2_messages = [
        "I'd say we average at least 3 times now",
        "Really? Once?",
    ]

    # Generate the dialogue turns
    dialogue_turns = []
    for i in range(len(u2_messages)):
        dialogue_turn = {
            "Steve": steve_messages[i],
            "u2": u2_messages[i]
        }
        dialogue_turns.append(dialogue_turn)

    # Add the final turn
    final_turn = {
        "Steve": "come on, it happened like one time!",
        "u2": reply
    }
    dialogue_turns.append(final_turn)

    # Create the JSON output
    output = {
        "turns": dialogue_turns
    }

    # Convert to JSON and return
    return json.dumps(output)

