import json

class DialogueGenerator:
    def __init__(self, context, relation, u2_reply):
        self.context = context
        self.relation = relation
        self.u2_reply = u2_reply
        self.turns = []

    def generate_turn(self):
        steve_msg = self.generate_steve_msg()
        u2_msg = self.generate_u2_msg(steve_msg)
        self.turns.append({"Steve": steve_msg, "u2": u2_msg})

