    turns = []
    steve_messages = ["Look, look how shiny this watch is.", "This watch is really special.", "Just think of all the things my grandfather must have done while wearing this watch!"]
    u2_messages = ["Is it really special compared to all the other fancy watches you have at home?", "Yeah, and I'm sure he must have worn it while taking a shower and doing his laundry too...", "Is it any more shiny than the last time you showed me?"]

    if num_turns == 0:
        return turns

    for i in range(len(steve_messages)):
        if i < num_turns - 1:
            turns.append({"Steve": steve_messages[i], "u2": u2_messages[i]})
        else:
            turns.append({"Steve": steve_messages[i], "u2": u2_message})

    return turns

