    given_u2 = "sure thing"

    # Generating 2 dialogue turns
    dialogue_turns = []
    steve_messages = ["get another one for me too, will you?", "do it again for me, will you?"]
    u2_messages = ["no worries", "no problem at all"]
    for i in range(2):
        dialogue_turn = {
            "Steve": steve_messages[i],
            "u2": u2_messages[i]
        }
        dialogue_turns.append(dialogue_turn)

    # Add the last turn
    last_steve_message = "get me another, mate."
    dialogue_turns.append({
        "Steve": last_steve_message,
        "u2": given_u2
    })

    # Output as JSON
    dialogue = {
        "turns": dialogue_turns
    }
    return json.dumps(dialogue, indent=4)


