    let responseJson = { turns: [] };

    const context = { relation: relation };

    const messages = [
        "Hey, I'm running a bit low on storage space, can you give me your USB stick to borrow?",
        "I just need to transfer some files from the lab to my computer.",
        "I'll be sure to handle it with care. Thanks for lending it to me!",
