        "Of course, Steve. What do you need it for?",
        "Be careful with it, okay? Some of the files on there are sensitive.",
    ];

    for (let i = 0; i < messages.length - 1; i++) {
        responseJson.turns.push({
            Steve: messages[i],
            [relation]: u2Responses[i],
        });
    }

    responseJson.turns.push({
        Steve: messages[messages.length - 1],
        [relation]: u2,
    });

    return responseJson;
}

